      value.textContent = `${volume.value}%`;
      this.save();
    });
    volumeLabel.append(volumeText, volume, value);
    pause.appendChild(volumeLabel);
    const questViews = {
      outstanding: this.quests.active(),
      completed: this.quests.completed()
    };
