async function selectVerb(page, name) {
        const label = await page.evaluate(name => window.__comradeCandidateTest.game.t(`verb.${name}`), name);
        for (let step = 0; step < 4; step++) {
          if ((await page.locator(".hud-verb").textContent()) === label) return;
          await page.locator(".hud-verb").click();
        }
        assert.fail(`Could not select ${name}`);
}
async function clickSceneTarget(page, id) {
        // Inspect hit geometry to choose an unobstructed point; do not invoke actions.
        const point = await page.evaluate(async id => {
          const { game } = window.__comradeCandidateTest;
          const { findTargetAt } = await import("/src/engine/SceneGeometry.js");
          const candidates = [];
          for (let y = 80; y < (id === "exit.archive.to_municipality" ? 660 : 580); y += 8) {
            for (let x = 16; x < 1260; x += 8) {
              if (findTargetAt(game.currentScene, { x, y }, target => game.targetAvailable(target))?.id === id) candidates.push({ x, y });
            }
          }
          if (!candidates.length) throw new Error(`No exposed click target: ${id}`);
          return candidates[Math.floor(candidates.length / 2)];
        }, id);
        await page.locator("#game").click({ position: point });
        return point;
}

async function choiceEndingContinue(page) {
  const label = await page.evaluate(() => window.__comradeCandidateTest.game.t("election.continue"));
  await page.locator(".ending-panel").getByRole("button", { name: label, exact: true }).click();
}

test/chapter1-campaign.test.js.before:
import test from "node:test";
import assert from "node:assert/strict";
import { chapter1 } from "../src/content/chapter1/index.js";
import { campaignDialogues, kioskPaperRule, kioskPamphletRule, campaignPosterRules } from "../src/content/chapter1/campaign.js";
import { campaignBg, campaignEn } from "../src/content/localization/chapter1Campaign.js";
import { pepaMusicRule, pepaPosterRule, pepaDiplomaRule } from '../src/content/chapter1/photoQuest.js';
import { Game } from "../src/engine/Game.js";
import { InventorySystem } from "../src/engine/InventorySystem.js";
import { QuestSystem } from "../src/engine/QuestSystem.js";
import { SaveSystem } from "../src/engine/SaveSystem.js";
import { DEFAULT_SAVE, VERBS } from "../src/engine/ids.js";
import { applyEffects, firstMatchingRule, requirementsMet } from "../src/engine/EffectSystem.js";

function context(overrides = {}) {
  const state = { ...structuredClone(DEFAULT_SAVE), ...overrides };
  const index = (entries) => Object.fromEntries(entries.map(entry => [entry.id, entry]));
  return {
    state,
    inventory: new InventorySystem(index(chapter1.items), state),
    quests: new QuestSystem(index(chapter1.quests), state)
  };
}

function target(id) {
  return chapter1.scenes.flatMap(scene => scene.interactables).find(entry => entry.id === id);
}

function use(rule, ctx) {
  assert.ok(requirementsMet(rule.requirements, ctx));
  applyEffects(rule.effects, ctx);
}

test("TV and poster share a one-time opening and persistent recap without changing inventory or meters", () => {
  const ctx = context();
  const beforeInventory = [...ctx.state.inventory];
  const tv = target("hotspot.apartment.tv");
  const poster = target("hotspot.apartment.campaign_poster");
  const opening = firstMatchingRule(tv.lookRules, ctx);
  assert.equal(opening.messageKey, "campaign.opening");
  use(opening, ctx);
  assert.equal(firstMatchingRule(poster.lookRules, ctx).messageKey, "campaign.opening_recap");
  assert.deepEqual(ctx.state.inventory, beforeInventory);
  assert.equal(ctx.state.suspicion, 0);
  let saved;
  const saves = new SaveSystem({ setItem(_key, value) { saved = value; }, getItem() { return saved; } });
  saves.save(ctx.state);
  const restored = context(saves.load());
  assert.equal(firstMatchingRule(tv.useRules, restored).messageKey, "campaign.opening_recap");
  assert.equal(firstMatchingRule(tv.lookRules, context({ chapter1Completed: true })).messageKey, "campaign.opening_recap");
});

test("photo and music issue a poster once, preserve the photo, and posting survives reload", () => {
  const ctx = context({ inventory: ['item.mitko_photo', 'item.accordion'], hasUnpaidBills: true });
  const kiosk = target("hotspot.square.kiosk");
  use(pepaMusicRule, ctx); use(pepaPosterRule, ctx);
  assert.deepEqual(ctx.state.inventory.sort(), ['item.accordion', 'item.campaign_pamphlets', 'item.mitko_photo']);
  assert.equal(ctx.state.hasFakeDiploma, false);
  assert.equal(ctx.state.completedQuests.includes("quest.chapter1.fake_diploma"), false);
  assert.equal(ctx.state.suspicion, 0);
  assert.equal(requirementsMet(pepaPosterRule.requirements, ctx), false);
  assert.equal(requirementsMet(target("hotspot.apartment.unpaid_bills").requirements, ctx), false);
  assert.equal(requirementsMet(kioskPamphletRule.requirements, ctx), false);

  // Dropping papers must not allow a second issuance or posting without possession.
  ctx.inventory.remove("item.campaign_pamphlets");
  ctx.state.droppedItems.push({ itemId: "item.campaign_pamphlets", sceneId: "scene.chapter1.village_square", x: 600, y: 540 });
  assert.equal(firstMatchingRule(campaignPosterRules, ctx), null);
  assert.equal(requirementsMet(kioskPamphletRule.requirements, ctx), false);
  ctx.inventory.add("item.campaign_pamphlets");
  ctx.state.droppedItems = [];
  use(firstMatchingRule(campaignPosterRules, ctx), ctx);
  assert.equal(ctx.state.flags.campaignPosted, true);
  assert.equal(ctx.inventory.has("item.campaign_pamphlets"), false);
  assert.equal(ctx.inventory.has('item.mitko_photo'), true);
  use(firstMatchingRule(campaignPosterRules, ctx), ctx);
  assert.equal(ctx.state.suspicion, 0);
  assert.equal(firstMatchingRule(target("hotspot.square.poster_board").lookRules, ctx).messageKey, "campaign.poster.posted");

  let saved;
  const saves = new SaveSystem({ setItem(_key, value) { saved = value; }, getItem() { return saved; } });
  saves.save(ctx.state);
  const restored = context(saves.load());
  assert.equal(restored.state.flags.campaignPosted, true);
  assert.equal(requirementsMet(kioskPamphletRule.requirements, restored), false);
});

test("legacy credentials can collect pamphlets once without bills or additional suspicion", () => {
  const ctx = context({ hasFakeDiploma: true, inventory: ["item.fake_diploma"], flags: { legacyPhotoCredentials: true } });
  use(kioskPamphletRule, ctx);
  assert.equal(ctx.inventory.has("item.campaign_pamphlets"), true);
  assert.equal(ctx.state.suspicion, 0);
  assert.equal(requirementsMet(kioskPamphletRule.requirements, ctx), false);
  assert.equal(requirementsMet(kioskPaperRule.requirements, context()), false);
  assert.equal(requirementsMet(kioskPaperRule.requirements, context({ chapter1Completed: true, inventory: ["item.unpaid_bills"] })), false);
  assert.equal(requirementsMet(kioskPamphletRule.requirements, context({ chapter1Completed: true, hasFakeDiploma: true })), false);
});

test("kiosk dialogue and direct item handover share transaction requirements", () => {
  const choice = campaignDialogues[0].nodes.start.choices.find(entry => entry.effect === pepaDiplomaRule);
  assert.ok(choice);
  assert.equal(requirementsMet(choice.requirements, context()), false);
  assert.equal(requirementsMet(choice.requirements, context({ inventory: ['item.mitko_photo','item.tony_diploma'], flags: { pepaMusicPlayed: true } })), true);
});

test("main quest guides opening, papers and posting, including legacy and dropped-paper states", () => {
  const ctx = context();
  const quest = chapter1.quests.find(entry => entry.id === "quest.chapter1.main");
  const stage = () => firstMatchingRule(quest.stages, ctx)?.id;
  assert.equal(stage(), "stage.main.hear_election");
  ctx.state.flags.chapter1OpeningHeard = true;
  assert.equal(stage(), "stage.main.prepare_campaign");
  ctx.state.hasFakeDiploma = true;
  ctx.state.flags.legacyPhotoCredentials = true;
  assert.equal(stage(), "stage.main.collect_pamphlets");
  use(kioskPamphletRule, ctx);
  assert.equal(stage(), "stage.main.post_campaign");
  ctx.inventory.remove("item.campaign_pamphlets");
  assert.equal(stage(), "stage.main.post_campaign");
  ctx.state.flags.campaignPosted = true;
  assert.equal(stage(), "stage.registration.evidence");
});

test("state-aware Look works through normal dispatch and after an authored approach sequence", () => {
  const ctx = context();
  const game = Object.create(Game.prototype);
  Object.assign(game, ctx, {
    selectedVerb: VERBS.LOOK,
    player: { animation: "idle" },
    t: key => key,
    save() {},
    renderUi() {},
    setStatusMessage(message) { this.message = message; },
    applyContentEffect(rule) { applyEffects(rule.effects, this.effectContext()); this.message = rule.messageKey; }
  });
  game.performTargetAction(target("hotspot.apartment.tv"));
  assert.equal(game.message, "campaign.opening");
  game.performTargetAction(target("hotspot.apartment.tv"));
  assert.equal(game.message, "campaign.opening_recap");
  ctx.state.flags.campaignPosted = true;
  const poster = target("hotspot.square.poster_board");
  game.completeInteractionActionSequence({ target: poster, verb: VERBS.LOOK, sequence: poster.actions.look });
  assert.equal(game.message, "campaign.poster.posted");
  game.performTargetAction({ id: "hotspot.other", lookKey: "look.other" });
  assert.equal(game.message, "look.other");
});

test("campaign strings and authored references are present in both languages", () => {
  assert.deepEqual(Object.keys(campaignBg).sort(), Object.keys(campaignEn).sort());
  const data = JSON.stringify([chapter1.scenes, chapter1.dialogues, chapter1.quests]);
  for (const [, key] of data.matchAll(/"(campaign\.[^"]+)"/g)) {
    assert.ok(campaignBg[key], `Missing Bulgarian: ${key}`);
    assert.ok(campaignEn[key], `Missing English: ${key}`);
    assert.equal(Array.isArray(campaignBg[key]), Array.isArray(campaignEn[key]));
  }
});

test/content-effects.test.js.before:
import { registerRule } from "../src/content/chapter1/registration.js";
import test from "node:test";
import assert from "node:assert/strict";
import { applyEffects, firstMatchingRule, requirementsMet } from "../src/engine/EffectSystem.js";
import { chapter1 } from "../src/content/chapter1/index.js";

function inventoryWith(...initialItems) {
  const items = new Set(initialItems);
  return {
    has: (itemId) => items.has(itemId),
    add: (itemId) => items.add(itemId),
    remove: (itemId) => items.delete(itemId),
    replace: (itemId, next) => { if (!items.has(itemId) || items.has(next)) return false; items.delete(itemId); items.add(next); return true; }
  };
}

test("content requirements combine inventory, flags, and state values", () => {
  const context = {
    state: { flags: { challengeStarted: true }, voteWon: false },
    inventory: inventoryWith("item.accordion")
  };
  assert.equal(requirementsMet({
    items: ["item.accordion"],
    flags: ["challengeStarted"],
    notFlags: ["guardAlerted"],
    state: { voteWon: false }
  }, context), true);
  assert.equal(requirementsMet({ items: ["item.missing"] }, context), false);
  assert.equal(requirementsMet({ stateMin: { cheapOffers: 2 }, stateMax: { cheapOffers: 4 } }, {
    state: { cheapOffers: 3 }
  }), true);
  assert.equal(requirementsMet({ stateMin: { cheapOffers: 4 } }, { state: { cheapOffers: 3 } }), false);
  assert.equal(requirementsMet({ stateMax: { cheapOffers: 2 } }, { state: { cheapOffers: 3 } }), false);
});

test("content effects update reusable state, inventory, and quest systems", () => {
  const completed = [];
  const inventory = inventoryWith();
  const state = { influence: 2, flags: {} };
  applyEffects([
    { type: "setFlag", key: "npcDistracted" },
    { type: "setState", key: "voteWon", value: true },
    { type: "adjustState", key: "influence", amount: 5 },
    { type: "addItem", itemId: "item.example" },
    { type: "completeQuest", questId: "quest.example" }
  ], {
    state,
    inventory,
    quests: { complete: (questId) => completed.push(questId) }
  });
  assert.equal(state.flags.npcDistracted, true);
  assert.equal(state.voteWon, true);
  assert.equal(state.influence, 7);
  assert.equal(inventory.has("item.example"), true);
  assert.deepEqual(completed, ["quest.example"]);
});

test("bounded state effects clamp counters and record a deterministic change time", () => {
  const state = { rakiaGlasses: 9, flags: {} };
  applyEffects([
    { type: "adjustState", key: "rakiaGlasses", amount: 4, min: 0, max: 10, timestampKey: "rakiaLastChangedAt" }
  ], { state, now: () => 123456 });
  assert.equal(state.rakiaGlasses, 10);
  assert.equal(state.rakiaLastChangedAt, 123456);

  applyEffects([
    { type: "adjustState", key: "rakiaGlasses", amount: -20, min: 0, max: 10, timestampKey: "rakiaLastChangedAt" }
  ], { state, now: () => 789000 });
  assert.equal(state.rakiaGlasses, 0);
  assert.equal(state.rakiaLastChangedAt, null);
});

test("unknown content effect types fail loudly", () => {
  assert.throws(
    () => applyEffects([{ type: "misspelledEffect" }], { state: { flags: {} } }),
    /Unknown content effect type/
  );
});

test("Tony vote vertical slice is reachable from authored Chapter 1 data", () => {
  const apartment = chapter1.scenes.find((scene) => scene.id === "scene.chapter1.apartment");
  const mehana = chapter1.scenes.find((scene) => scene.id === "scene.chapter1.mehana");
  const accordion = apartment.interactables.find((target) => target.id === "hotspot.apartment.accordion");
  const tony = mehana.npcs.find((target) => target.id === "npc.tony_fridge");
  const mitkoGlass = mehana.interactables.find(
    (target) => target.id === "hotspot.mehana.bai_mitko_rakia_glass"
  );
  const tonyDialogue = chapter1.dialogues.find((dialogue) => dialogue.id === "dialogue.tony_fridge");
  const inventory = inventoryWith(accordion.takeItemId);
  const state = {
    tonyVote: false,
    swappedOwnRakiaWithWater: false,
    influence: 0,
    suspicion: 0,
    publicMood: 50,
    flags: { tonyChallengeStarted: true }
  };
  const completed = [];
  const context = {
    state,
    inventory,
    quests: { complete: (questId) => completed.push(questId) }
  };

  const distraction = firstMatchingRule(
    tony.itemUseRules.filter((rule) => rule.itemId === "item.accordion"),
    context
  );
  assert.ok(distraction);
  applyEffects(distraction.effects, context);
  inventory.add("item.fountain_water_bottle");
  const swap = firstMatchingRule(
    mitkoGlass.itemUseRules.filter((rule) => rule.itemId === "item.fountain_water_bottle"),
    context
  );
  assert.equal(swap.messageKey, "msg.water_swap_ready");
  applyEffects(swap.effects, context);

  assert.equal(state.swappedOwnRakiaWithWater, true);
  assert.equal(state.tonyVote, false);
  const finish = firstMatchingRule(tonyDialogue.nodes.start.choices, context);
  const finishChoice = tonyDialogue.nodes.start.choices.find(
    (choice) => choice.textKey === "dialogue.tony.choice.finish_challenge"
  );
  assert.equal(finish, finishChoice);
  applyEffects(finishChoice.effect.effects, context);

  assert.equal(state.tonyVote, true);
  assert.equal(state.influence, 25);
  assert.equal(state.suspicion, 10);
  assert.equal(state.publicMood, 55);
  assert.equal(inventory.has("item.fountain_water_bottle"), false);
  assert.deepEqual(completed, ["quest.chapter1.tony_vote"]);
});

test("obsolete bills and envelope recipe cannot bypass the new diploma quest", () => {
  const bills = chapter1.items.find((item) => item.id === "item.unpaid_bills");
