    flags: {}
  };
  const completed = [];
  const context = {
    state,
    inventory,
    quests: { complete: (questId) => completed.push(questId) }
  };
  const assembly = firstMatchingRule(
    bills.itemUseRules.filter((rule) => rule.itemId === "item.empty_envelope"),
