  );

  assert.ok(assembly);
  applyEffects(assembly.effects, context);
  assert.equal(assembly.reject, true);
  assert.equal(inventory.has("item.unpaid_bills"), true);
  assert.equal(inventory.has("item.empty_envelope"), true);
